import React, { useContext } from 'react';

import { PluginsContext } from './../../../../ricos-context/index.js';
import type { IToolbarItem } from './../../../../ricos-types/toolbar-types.js';

import { CustomHeadingButton } from '../CustomHeadingButton/custom-heading-button.js';
import { HeadingButton } from '../HeadingButton/heading-button.js';

export const HeadingButtonSwitch = ({
  toolbarItem,
  dataHook,
}: {
  toolbarItem: IToolbarItem;
  dataHook?: string;
}) => {
  const plugins = useContext(PluginsContext);
  const headingsData = plugins?.getConfig('wix-rich-content-plugin-headings');

  return headingsData?.allowHeadingCustomization ? (
    <CustomHeadingButton toolbarItem={toolbarItem} dataHook={dataHook} />
  ) : (
    <HeadingButton toolbarItem={toolbarItem} dataHook={dataHook} />
  );
};
