import React from 'react';

import type { DocumentStyle } from './../ricos-content/index.js';
import type { HeadingType } from './../ricos-types/index.js';
import { DRAFT_TO_DOC_TYPE_WITH_LISTS } from './../ricos-types/index.js';

export const headingsMap = {
  'header-one': 'Heading 1',
  'header-two': 'Heading 2',
  'header-three': 'Heading 3',
  'header-four': 'Heading 4',
  'header-five': 'Heading 5',
  'header-six': 'Heading 6',
  unstyled: 'P',
};

const findOsName = () => {
  if (navigator.userAgent.indexOf('Win') !== -1) {
    return 'Windows';
  }
  if (navigator.userAgent.indexOf('Mac') !== -1) {
    return 'MacOS';
  }
  return null;
};

const headingShortcuts = {
  MacOS: (number: $TSFixMe) => ` (⌘⌥${number})`,
  Windows: (number: $TSFixMe) => ` (Ctrl+Alt+${number})`,
};

export const translateHeading = (option = 'P', t: $TSFixMe, shouldAddShortcut = false) => {
  const number = parseInt(option.slice(-1)) ? option.slice(-1) : undefined;
  const osName = findOsName();
  const shortcut = shouldAddShortcut && osName ? headingShortcuts[osName](number || 0) : undefined;
  return option === 'P'
    ? t('FormattingToolbar_TextStyle_Paragraph', shortcut && { shortcut })
    : t('FormattingToolbar_TextStyle_Heading', shortcut ? { number, shortcut } : { number });
};

export const getCustomHeadingsLabel = (
  selectedHeading: $TSFixMe,
  t: $TSFixMe,
  publicCommands: $TSFixMe
) => {
  const label = translateHeading(headingsMap[selectedHeading as keyof typeof headingsMap], t);
  const inlineStyles = publicCommands.getInlineStylesInSelection() || {};

  const isAsteriskVisible = hasStyleChanges(
    selectedHeading,
    inlineStyles,
    publicCommands.getDocumentStyle()
  );

  return (
    <>
      {label}
      <span style={{ width: '1ch', marginInline: '-3px' }}>{isAsteriskVisible ? '*' : null}</span>
    </>
  );
};

export const hasStyleChanges = (
  currentHeading: HeadingType,
  inlineStyles: Record<string, string>,
  documentStyle?: DocumentStyle
) => {
  const key =
    DRAFT_TO_DOC_TYPE_WITH_LISTS[currentHeading as keyof typeof DRAFT_TO_DOC_TYPE_WITH_LISTS];
  const headerStyle = documentStyle?.[key as keyof DocumentStyle] || {};
  return Object.entries(inlineStyles).some(
    ([key, value]) => headerStyle[key as keyof typeof headerStyle] !== value
  );
};
