import React from 'react';

import type { PublicCommands, TFunction } from './../../ricos-types/index.js';
import {
  getCustomHeadingsLabel,
  headingsMap,
  translateHeading,
} from './../../_shared/headings-dropdown-utils.js';

export const getCurrentHeadingIcon = (
  allowHeadingCustomization: boolean,
  publicCommands: PublicCommands,
  t: TFunction
): ((props: $TSFixMe) => JSX.Element) => {
  const selectedHeading = publicCommands.getCurrentHeading();

  return () => (
    <div>
      {allowHeadingCustomization
        ? getCustomHeadingsLabel(selectedHeading, t, publicCommands)
        : translateHeading(headingsMap[selectedHeading as keyof typeof headingsMap], t)}
    </div>
  );
};
