/* oxlint-disable no-console */
/* oxlint-disable brace-style */
import type { Dispatch, SetStateAction } from 'react';

import type {
  EventSource,
  Modal,
  ModalHandle,
  ModalSettings,
  PluginPanel,
  PolicySubscriber,
  PublisherProvider,
  Subscription,
  SubscriptorProvider,
} from './../ricos-types/index.js';
import { logInvariant } from './../_shared/log-invariant.js';
import { uuid } from './../wix-rich-content-common/index.js';

type Topics = ['ricos.modals.functionality.modalOpened', 'ricos.modals.functionality.modalClosed'];

const TOPICS: Topics = [
  'ricos.modals.functionality.modalOpened',
  'ricos.modals.functionality.modalClosed',
];

type ModalWithRef<P = any, R = any> = Modal<P, R> & {
  modalRef: { current: R | null };
};

export type ModalState = Record<string, ModalWithRef>;

export class ModalService implements PolicySubscriber<Topics>, EventSource<Topics> {
  // oxlint-disable-next-line no-useless-constructor
  constructor(
    private modalSettings: ModalSettings,
    private state: { get: () => ModalState; set: Dispatch<SetStateAction<ModalState>> },
    private externalModalState: { set: Dispatch<SetStateAction<boolean>> }
  ) {}

  id = 'ricos-modal-service';

  topicsToPublish = TOPICS;

  topicsToSubscribe = TOPICS;

  publishers!: PublisherProvider<
    ['ricos.modals.functionality.modalOpened', 'ricos.modals.functionality.modalClosed']
  >;

  subscriptors!: SubscriptorProvider<
    ['ricos.modals.functionality.modalOpened', 'ricos.modals.functionality.modalClosed']
  >;

  public setModalRef(modalId: string, ref: any): void {
    this.state.set((prev: ModalState): ModalState => {
      const modal = prev[modalId];
      if (!modal || Object.keys(modal.modalRef?.current).length > 0) {
        return prev;
      }
      modal.modalRef.current = ref;
      return {
        ...prev,
        [modalId]: modal,
      };
    });
  }

  public openModal<P, R>(config: Modal<P, R>): ModalHandle<P, R> {
    const modalSessionId = uuid();
    if (this.state.get()[config.id]) {
      console.warn(`Reopening modal ${config.id} that's already open`);
    }

    if (config.type === 'exclusive') {
      const openModals = this.getOpenModals();
      openModals.forEach(openModal => {
        if (openModal.id !== config.id) {
          this.closeModal(openModal.id);
        }
      });
    }

    const modalRef = { current: {} as R };
    const modal: ModalWithRef<P, R> = {
      ...config,
      componentProps: { ...config.componentProps, modalSessionId },
      modalRef,
    };
    this.state.set(
      (prev: ModalState): ModalState => ({
        ...prev,
        [config.id]: modal,
      })
    );

    this.publishers.byTopic('ricos.modals.functionality.modalOpened').publish({
      id: config.id,
      entryType: config.entryType,
      dropdownValue: config.dropdownValue,
      modalSessionId,
    });
    this.modalSettings?.onModalOpen?.();

    return {
      modalRef,
      patchProps: (newProps: Partial<P>) => {
        this.state.set((prev: ModalState): ModalState => {
          const modal = prev[config.id];
          if (!modal) {
            logInvariant(new Error(`Patching modal with id ${config.id} which is not open`));
            return prev;
          }
          return {
            ...prev,
            [config.id]: {
              ...modal,
              modalRef: { current: modal.modalRef?.current },
              componentProps: { ...modal.componentProps, ...newProps },
            } as ModalWithRef<P, R>,
          };
        });
      },
      close: () => this.closeModal(modal.id),
    };
  }

  public togglePluginPanel<P, R>({ isMobile, ...params }: PluginPanel<P, R>): void {
    if (this.isModalOpen(params.id)) {
      this.closeModal(params.id);
      return;
    }

    this.openModal({
      enableDrag: !isMobile,
      dragHandleSelector: '[data-drag-handler]',
      layout: {
        desktop: params.positioning?.referenceElement ? 'floating' : 'dialog',
        mobile: params.mobileLayout ?? 'fullscreen',
      },
      withTransition: !isMobile,
      type: 'exclusive',
      disableArrowNavigation: true,
      onClickOutside: {
        on: 'pointerup',
        handler: e => {
          if (params.focusReturnElement && !params.focusReturnElement?.contains(e.target as Node)) {
            this.closeModal(params.id);
            return;
          }

          const excludeElement = params.positioning.referenceElement;
          if (!excludeElement?.contains?.(e.target as Node)) {
            this.closeModal(params.id);
            return;
          }
        },
      },
      ...params,
    });
  }

  public closeModal(modalId: string): boolean {
    const modal = this.state.get()[modalId];
    if (!modal) {
      console.warn(`Fail to close modal: ${modalId} is not open`);
      return false;
    } else {
      this.state.set(prevState => {
        const { [modalId]: _, ...remainingModals } = prevState;
        return remainingModals;
      });
      this.publishers.byTopic('ricos.modals.functionality.modalClosed').publish(modal);
      this.modalSettings?.onModalClose?.();

      return true;
    }
  }

  public getOpenModals(): Modal[] {
    return Object.values(this.state.get());
  }

  public isModalOpen(id: string): boolean {
    const modal = this.state.get()[id];
    return !!modal;
  }

  public onModalOpened(onOpen: (id: string) => unknown): Subscription {
    return this.subscriptors
      .byTopic('ricos.modals.functionality.modalOpened')
      .subscribe((_topic, data) => {
        onOpen(data.id);
      });
  }

  public onModalClosed(onClose: (modal: Modal) => unknown): Subscription {
    return this.subscriptors
      .byTopic('ricos.modals.functionality.modalClosed')
      .subscribe((_topic, data) => {
        onClose(data as Modal);
      });
  }

  /**
   * Call before opening an external (non-Ricos-rendered) modal-like flow,
   * e.g. the host's Media Manager — its DOM isn't visible to Ricos, so the
   * plugin toolbar's outside-click dismissal can't recognize it on its own.
   * See useDismissPluginToolbarOnOutsideClick.
   *
   * Deliberately does NOT publish to `modalOpened` — that topic already
   * drives the `onPluginModalOpened` BI callback via `openModal()`, which
   * expects a real `{ id, entryType, dropdownValue, modalSessionId }`
   * payload. Publishing here would fire that callback with garbage data.
   */
  public notifyExternalModalOpened(): void {
    this.externalModalState.set(true);
  }

  /**
   * Also called from several pre-existing, unrelated "cancel" flows (dev-only
   * pick-media paths) that have nothing to do with the external-modal flag
   * above — those calls are harmless no-ops against it since they can't run
   * concurrently with a real external modal session in practice.
   */
  public notifyExternalModalClosed(options: { focusReturnElement?: HTMLElement } = {}): void {
    this.externalModalState.set(false);
    this.publishers.byTopic('ricos.modals.functionality.modalClosed').publish(options);
  }

  public getModal(id: string): Partial<Modal> | undefined {
    return this.state.get()[id];
  }
}
