import { ChevronDownSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../../ricos-modals/modal-service-provider.js';
import { Node_Type } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { IToolbarItem } from './../../../../ricos-types/index.js';
import { headingsMap, translateHeading } from './../../../../_shared/headings-dropdown-utils.js';
import { ToolbarButton } from './../../../../_shared/toolbar-button/toolbar-button.js';

export const HeadingButton: React.FC<{ toolbarItem: IToolbarItem; dataHook?: string }> = ({
  toolbarItem,
  dataHook,
}) => {
  const { t } = useContext(RicosContext);
  const isModalOpen = useModalState(getIsModalOpen(`${Node_Type.HEADING}.modal`));
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);

  const selectedHeading = toolbarItem.attributes.selectedHeading;

  const Label = translateHeading(headingsMap[selectedHeading as keyof typeof headingsMap], t);

  return (
    <ToolbarButton
      ref={setReferenceElement}
      disabled={toolbarItem.attributes.disabled}
      active={isModalOpen}
      onClick={e => toolbarItem.commands?.click({ referenceElement, clickFromKeyboard: !e.detail })}
      // The heading name goes through `label` to be typeset by WDS's label tokens rather than
      // at the button's font-size in the icon box. That suppresses the tooltip, so its text
      // becomes the accessible name.
      ariaLabel={t(toolbarItem.presentation?.tooltip)}
      label={Label}
      suffix={ChevronDownSmall}
      dataHook={dataHook}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
