import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { HeadingNode, ParagraphNode, Resolver } from './../../ricos-types/index.js';
import { isDefined } from './../../wix-rich-content-common/Utils/is-defined.js';

import { deepEqual } from '../deep-equal.js';

export const isTextStylesMatchDocumentStylesResolver: Resolver<boolean> = (
  content = [],
  { styles, converters }
) => {
  const currentNode = content.filter(
    node => node.type.name === Node_Type.HEADING || node.type.name === Node_Type.PARAGRAPH
  );

  let stylesMatched = true;
  if (currentNode.length === 1) {
    const ricosCurrentNode = converters.fromPmNode(currentNode[0].toJSON());

    const currentNodeDocumentsStyles = styles
      .getDocumentStyle()
      .getDecorations(ricosCurrentNode as ParagraphNode | HeadingNode);
    const textsDecorations = (ricosCurrentNode?.nodes ?? [])
      .filter(node => {
        return node.type === Node_Type.TEXT;
      })
      .map(node => {
        return node.textData?.decorations;
      })
      .flat()
      .filter(isDefined);

    stylesMatched = textsDecorations.every(decoration => {
      const currentDocumentStyleDecoration = currentNodeDocumentsStyles.find(documentStyle => {
        return documentStyle.type === decoration.type;
      });
      if (currentDocumentStyleDecoration) {
        const removeNullReplacer = (key: $TSFixMe, value: $TSFixMe) =>
          value === null ? undefined : value;

        const cleanDecoration = JSON.parse(JSON.stringify(decoration, removeNullReplacer));
        const cleanedCurrentDocumentStyleDecoration = JSON.parse(
          JSON.stringify(currentDocumentStyleDecoration, removeNullReplacer)
        );
        if (
          currentDocumentStyleDecoration &&
          !deepEqual(cleanedCurrentDocumentStyleDecoration, cleanDecoration)
        ) {
          return false;
        }
      } else {
        return false;
      }

      return true;
    });
  }

  return stylesMatched;
};
